import{_ as n,a0 as p,w as l,s as f,ao as o,I as r,x as s,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"什么是 Firefox ESR？如何在 Ubuntu 中安装它？ | LCTT x X-CMD","titleTemplate":false,"description":"什么是 Firefox ESR？如何在 Ubuntu 中安装它？ | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什么是 Firefox ESR？如何在 Ubuntu 中安装它？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什么是 Firefox ESR？如何在 Ubuntu 中安装它？ | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221201.5 ⭐️⭐️ What is Firefox ESR How to Install it in Ubuntu","title":"什么是 Firefox ESR？如何在 Ubuntu 中安装它？","tag":"202301","desc":""},"relativePath":"202301/20221201.5 ⭐️⭐️ What is Firefox ESR How to Install it in Ubuntu.md","filePath":"[post].md"}'),u={name:"202301/20221201.5 ⭐️⭐️ What is Firefox ESR How to Install it in Ubuntu.md"};function d(h,i,g,b,x,k){const e=p("Link");return l(),f("div",null,[i[24]||(i[24]=o('<h1 id="什么是-firefox-esr-如何在-ubuntu-中安装它" tabindex="-1">什么是 Firefox ESR？如何在 Ubuntu 中安装它？ <a class="header-anchor" href="#什么是-firefox-esr-如何在-ubuntu-中安装它" aria-label="Permalink to “什么是 Firefox ESR？如何在 Ubuntu 中安装它？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/07/165704ojar9wfkvptwop0w.jpg" alt=""></p><p>Ubuntu 的 Snap 版本你不喜欢？不喜欢每一次 Firefox 的发布都要不断地改变东西？如果你重视稳定性而不是功能，你可以试试 Firefox ESR 版本。</p><h3 id="什么是-firefox-esr" tabindex="-1">什么是 Firefox ESR？ <a class="header-anchor" href="#什么是-firefox-esr" aria-label="Permalink to “什么是 Firefox ESR？”">​</a></h3><p>Firefox ESR 是 Firefox 的特别版，它不一定像普通版那样每月都有新功能，但它能提供稳定和安全的浏览体验。这适用于企业、组织和机构，在这些地方，稳定性和核心功能比闪亮的新功能更重要。</p><p>可以把 Firefox ESR 看作是 Linux 发行版的长期稳定版本。它们不一定得到全新的功能，但它们会得到定期的安全和维护更新。这给了用户一个熟悉和稳定的环境。</p><h4 id="你为什么要关心-firefox-esr" tabindex="-1">你为什么要关心 Firefox ESR？ <a class="header-anchor" href="#你为什么要关心-firefox-esr" aria-label="Permalink to “你为什么要关心 Firefox ESR？”">​</a></h4><p>Firefox 几乎每个月都会发布一个新版本。它包含安全和功能更新。</p><p>但有些人可能不喜欢各种功能的加入和删除。如果在更新之后，你一直想知道某些设置到哪里去了，或者不喜欢与以前不同的东西，Firefox ESR 可能值得一试。</p><p>基本上，如果你更看重稳定性而不是新功能，那么 Firefox ESR 就适合你。这也是 Debian 中携带的 Firefox 版本，Debian 以其是市场上最稳定的发行版之一而闻名。</p><p>让我告诉你如何在 Ubuntu 上获得 Firefox ESR。<strong>你可以同时安装 Firefox 和 Firefox-ESR 两个版本。它们的标识没有视觉上的区别，所以你必须注意你打开的是哪个火狐版本。</strong></p><h3 id="在-ubuntu-中安装-firefox-esr" tabindex="-1">在 Ubuntu 中安装 Firefox ESR <a class="header-anchor" href="#在-ubuntu-中安装-firefox-esr" aria-label="Permalink to “在 Ubuntu 中安装 Firefox ESR”">​</a></h3><p>在进入安装之前，让我来分享一下普通 Firefox 和 Firefox-ESR 之间的版本差异是什么。在写这篇文章的时候：</p><ul><li>Firefox 的版本是 <strong>107.0-2</strong>。</li><li>Firefox-ESR 目前的版本是 <strong>102.5.0esr</strong>。</li></ul><p>所以，如果这对你来说没问题，让我们看看第一个方法。</p><h4 id="方法-1-使用-ppa-安装-firefox-esr" tabindex="-1">方法 1：使用 PPA 安装 Firefox-ESR <a class="header-anchor" href="#方法-1-使用-ppa-安装-firefox-esr" aria-label="Permalink to “方法 1：使用 PPA 安装 Firefox-ESR”">​</a></h4><p>Firefox-ESR 在 Ubuntu 的默认仓库中是不可用的，所以你可以使用 PPA。</p><p>PPA 只不过是一个由个别技术人员或开发者维护的仓库，拥有默认仓库所没有的东西。</p>',18)),r("p",null,[i[1]||(i[1]=s("如果你想了解更多关于 PPA 的信息，我建议你查看我们的其他指南，其中解释了 ",-1)),t(e,{href:"https://itsfoss.com/ppa-guide/"},{default:a(()=>[...i[0]||(i[0]=[s("如何在 Linux 上使用 PPA",-1)])]),_:1}),i[2]||(i[2]=s("。",-1))]),i[25]||(i[25]=o('<p>打开你的终端，使用给定的命令来添加 Firefox-ESR 的 PPA：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:mozillateam/ppa</span></span></code></pre></div><p>然后按回车键确认你要添加 PPA：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/add-firefox-esr-repository-in-ubuntu.png" alt="add firefox esr repository in ubuntu"></p><p>完成后，你需要更新 Ubuntu 中的仓库索引，以便从这些变化中生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>现在，你可以通过使用给定的命令来安装 Firefox-ESR：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install firefox-esr</span></span></code></pre></div><p>接下来，你可以使用给定的命令来检查你系统中 Firefox-ESR 的安装版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firefox-esr -v</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/check-installed-version-of-firefox-esr-in-ubuntu.png" alt="check installed version of firefox esr in ubuntu"></p><p>如何从 Ubuntu 卸载 Firefox-ESR？</p><p>如果 ESR 对你的工作来说感觉太过时了，或者由于其他原因你想从你的系统中删除它，你可以按照以下步骤删除 Firefox-ESR 包和仓库。</p><p>首先，让我们用下面的方法删除 Firefox-ESR 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove firefox-esr</span></span></code></pre></div>',15)),r("p",null,[i[4]||(i[4]=s("现在，你可以使用给定的命令来 ",-1)),t(e,{href:"https://itsfoss.com/how-to-remove-or-delete-ppas-quick-tip/"},{default:a(()=>[...i[3]||(i[3]=[s("从 Ubuntu 删除 PPA",-1)])]),_:1}),i[5]||(i[5]=s("：",-1))]),i[26]||(i[26]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository --remove ppa:mozillateam/ppa</span></span></code></pre></div><p>这就完成了！</p><h4 id="方法-2-使用-snap-安装-firefox-esr" tabindex="-1">方法 2：使用 Snap 安装 Firefox-ESR <a class="header-anchor" href="#方法-2-使用-snap-安装-firefox-esr" aria-label="Permalink to “方法 2：使用 Snap 安装 Firefox-ESR”">​</a></h4><p>不管你爱不爱它，Snap 在 Ubuntu 上是预先配置好的，我发现使用 Snap 是安装软件包的一个很好的方法，特别是当你想避免从源码构建它们或使用 PPA 时。</p><p>使用 Snap 安装 Firefox-ESR，你需要做的就是使用给定的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap install firefox --channel=esr/stable</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/install-firefox-esr-using-snaps-in-ubuntu.png" alt="install firefox esr using snaps in ubuntu"></p><p>如何删除 Firefox-ESR Snap？</p>',8)),r("p",null,[i[7]||(i[7]=s("要删除 Firefox-ESR（snap 包），请使用 ",-1)),t(e,{href:"https://itsfoss.com/remove-snap/"},{default:a(()=>[...i[6]||(i[6]=[s("snap remove 命令",-1)])]),_:1}),i[8]||(i[8]=s("：",-1))]),i[27]||(i[27]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap remove firefox</span></span></code></pre></div><p>这就完成了！</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我在本指南中解释了如何使用多种方法在 Ubuntu 中安装 Firefox-ESR。我个人使用 Firefox-ESR 而不是普通版本，因为我有随机崩溃的情况。</p><p>自从我改用 Firefox-ESR 后，一切都变得稳如磐石。如果你也有同样的问题，你应该试一试。</p><hr>',6)),r("p",null,[i[10]||(i[10]=s("via: ",-1)),t(e,{href:"https://itsfoss.com/firefox-esr-ubuntu/"},{default:a(()=>[...i[9]||(i[9]=[s("https://itsfoss.com/firefox-esr-ubuntu/",-1)])]),_:1})]),r("p",null,[i[15]||(i[15]=s("作者：",-1)),t(e,{href:"https://itsfoss.com/author/sagar/"},{default:a(()=>[...i[11]||(i[11]=[s("Sagar Sharma",-1)])]),_:1}),i[16]||(i[16]=s(" 选题：",-1)),t(e,{href:"https://github.com/lkxed"},{default:a(()=>[...i[12]||(i[12]=[s("lkxed",-1)])]),_:1}),i[17]||(i[17]=s(" 译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:a(()=>[...i[13]||(i[13]=[s("geekpi",-1)])]),_:1}),i[18]||(i[18]=s(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[14]||(i[14]=[s("wxy",-1)])]),_:1})]),r("p",null,[i[21]||(i[21]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[19]||(i[19]=[s("LCTT",-1)])]),_:1}),i[22]||(i[22]=s(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...i[20]||(i[20]=[s("Linux中国",-1)])]),_:1}),i[23]||(i[23]=s(" 荣誉推出",-1))])])}const E=n(u,[["render",d]]);export{F as __pageData,E as default};
